<script lang="ts">
 import {languageOverrides} from "./localization";
 import {translator} from "./i18n";import {onMount} from 'svelte';import {invoke} from '@tauri-apps/api/core';import {native,ask} from './storage';import {requestPassword} from './password-prompt';import {LockKeyhole,UnlockKeyhole} from "./icons";export let language:'ru'|'ro'|"en";export let onsave:()=>Promise<boolean>;export let onlock:()=>Promise<void>;let status={portable:false,encrypted:false},error='',busy=false; $:ru=language==='ru';async function refresh(){if(native)status=await invoke('database_protection');}onMount(()=>void refresh().catch(e=>error=String(e)));async function change(remove=false){try{busy=true;if(!await onsave())return;if(remove&&!await ask(t('Снять пароль и сохранить базу без шифрования?','Eliminați parola și salvați baza fără criptare?')))return;const password=remove?'':await requestPassword(t('Новый пароль базы','Parola nouă a bazei'),true);if(password===null)return;await invoke('change_database_password',{password});await refresh();error='';}catch(e){error=String(e);}finally{busy=false;}}
 $:t=translator(language,$languageOverrides);
</script>
<article class="panel database-security"><h2>{t('Защита базы данных','Protecția bazei de date')}</h2>{#if error}<p class="alert error">{error}</p>{/if}{#if !native}<p>{t('Шифрование доступно в настольной программе.','Criptarea este disponibilă în aplicația desktop.')}</p>{:else if !status.portable}<p>{t('Сначала используйте «Файл → Сохранить базу как…», чтобы создать файл ODB.','Folosiți mai întâi «Fișier → Salvează baza ca…» pentru a crea un fișier ODB.')}</p>{:else}<p>{status.encrypted?(t('Файл базы зашифрован. При открытии требуется пароль.','Fișierul bazei este criptat. Deschiderea necesită parola.')):(t('Файл базы хранится без шифрования.','Fișierul bazei nu este criptat.'))}</p><div class="actions"><button class="button" disabled={busy} onclick={()=>change()}><LockKeyhole size={17}/>{status.encrypted?(t('Изменить пароль','Schimbă parola')):(t('Установить пароль','Setează parola'))}</button>{#if status.encrypted}<button class="button secondary" disabled={busy} onclick={()=>change(true)}><UnlockKeyhole size={17}/>{t('Снять пароль','Elimină parola')}</button><button class="button secondary" disabled={busy} onclick={onlock}>{t('Заблокировать базу','Blochează baza')}</button>{/if}</div><p class="quiet-note">{t('Пароль не сохраняется на компьютере. Сохраните его в надёжном месте: восстановление забытого пароля пока недоступно. Резервная копия, создаваемая перед установкой пароля, остаётся незашифрованной. Ранее созданные копии также не изменяются. Храните их в защищённом месте.','Parola nu se salvează pe calculator. Păstrați-o într-un loc sigur: recuperarea parolei uitate nu este încă disponibilă. Copia de siguranță creată înainte de setarea parolei rămâne necriptată. Copiile anterioare nu se modifică. Păstrați-le într-un loc protejat.')}</p>{/if}</article>
<style>.database-security{display:grid;gap:18px}.database-security h2,.database-security p{margin:0}.actions{display:flex;gap:10px;flex-wrap:wrap}</style>
